# Keep the source panels in GitHub and deploy the verified annual data files.
files <- rsconnect::listDeploymentFiles(".")
annual_files <- list.files("app-data", recursive = TRUE, full.names = TRUE)
source_panels <- c("MSA_analysis_data.dta", "master_county_build.dta", "State_CH_analysis_data.dta")
if (!length(annual_files) || !all(annual_files %in% files))
  stop("The deployment bundle is missing prepared app data.")
if (any(source_panels %in% files))
  stop("The deployment bundle should use annual data files instead of full panels.")
if (!all(c("app.R", "renv.lock", "pdf_help.R", "state_ch_adjustments.R", "state_ch_adjustment_interface.R", "State_CH_adjustment_counties_data.dta", "MSA_CH_county_membership.dta", "MSA_CH_county_cluster_membership.dta") %in% files))
  stop("The deployment bundle is missing the app or its dependency lockfile.")
help <- new.env(parent = baseenv())
sys.source("pdf_help.R", envir = help)
notes <- help$pdf_help_manifest()
help_files <- file.path("www", "help", c(notes$file, notes$image))
if (!all(help_files %in% files))
  stop("The deployment bundle is missing a PDF explanation or its image preview.")
output <- Sys.getenv("APP_TEST_OUTPUT", unset = "/tmp/agglomeration-checks")
dir.create(output, recursive = TRUE, showWarnings = FALSE)
writeLines(files, file.path(output, "deployment_files.txt"))
cat("Deployment includes", length(annual_files), "prepared data files.\n")
cat("Deployment includes", nrow(notes), "PDF explanations and their image previews.\n")
